import { SPECIES } from './ecosystem.mjs';
import { ENVIRONMENTS, THEMES, WEATHERS, EXTRA_SPECIES, SCENARIOS } from './experiments.mjs';

const safe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createDevMenu(api){
 let active='world';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
 const tabs=[['world','Worlds'],['life','Life'],['player','Wanderer'],['events','Weather & events'],['feel','Tuning'],['journal','Journal']];
 const spriteTag=name=>`<canvas data-sprite="${name}" width="16" height="16"></canvas>`;
 const check=(key,title,help,value)=>`<label class="dev-switch"><span><b>${title}</b><small>${help}</small></span><input type="checkbox" data-option="${key}" ${value?'checked':''}></label>`;
 function open(category=active){
  active=category;const {eco,reduced}=api.state();const p=eco.player;
  let content='';
  if(active==='world')content=`<p class="dev-intro">New worlds replace the current habitat. Undo brings it back, including your wanderer and discoveries.</p><div class="dev-form-grid"><label>Environment<select id="dev-environment">${Object.entries(ENVIRONMENTS).map(([id,e])=>`<option value="${id}" ${eco.environment===id?'selected':''}>${e.name}</option>`).join('')}</select></label><label>Theme<select id="dev-theme">${Object.entries(THEMES).map(([id,e])=>`<option value="${id}" ${eco.theme===id?'selected':''}>${e.name}</option>`).join('')}</select></label></div><label class="dev-field">Seed<input id="dev-seed" value="${safe(eco.seed)}" maxlength="28" autocomplete="off" spellcheck="false"></label><div class="dev-inline-actions"><button id="apply-theme" class="secondary">Apply theme only</button><button id="generate-lab" class="primary">Generate test world</button></div><p class="dev-help">Test worlds include the expanded wildlife. Feywild also seeds crystals, wisps, slimes, and drakes.</p><h3 class="dev-heading">Scenario starters</h3><div class="scenario-list">${SCENARIOS.map(s=>`<button data-scenario="${s.id}" class="scenario-card"><span>${s.name}</span><small>${s.description}</small><b>Run scenario · replaces world</b></button>`).join('')}</div>`;
  if(active==='life')content=`<p class="dev-intro">Each creature follows its own rules. “Place” puts it on your brush; “Add 5” scatters a small group into suitable habitat.</p><div class="creature-catalog">${Object.entries(EXTRA_SPECIES).map(([id,s])=>`<article class="creature-entry"><div class="creature-title">${spriteTag(id)}<div><h3>${s.name}</h3><span>${s.fantasy?'Fantasy · ':''}${s.role}</span></div></div><p>${s.description}</p><div><button data-place="${id}" class="secondary">Place</button><button data-add="${id}" class="secondary">Add 5</button></div></article>`).join('')}</div><h3 class="dev-heading">More flora</h3><div class="dev-inline-actions"><button data-place="mushroom" class="secondary">${spriteTag('mushroom')}Mushrooms</button><button data-place="crystal" class="secondary">${spriteTag('crystal')}Crystals</button></div><p class="dev-help">Mushrooms feed decomposers and fireflies. Crystals sustain wisps, which grow luminous flowers.</p>`;
  if(active==='player')content=`<p class="dev-intro">Become a small part of the world. Walk to landmarks, read what remains, gather resources, and build things that change the ecology.</p><div class="wanderer-card">${spriteTag('wanderer')}<div><h3>${p?'The wanderer':'An ordinary traveller'}</h3><p>${p?`${p.discovered} places discovered · ${p.insight} insight`:'8 seeds · 6 wood · 4 stone to begin'}</p></div><button id="enter-world" class="primary">${p?.enabled?'Continue walking':'Enter world'}</button></div>${p?`<div class="inventory-line"><span>${Math.round(p.hp)} health</span><span>${Math.round(p.energy)} energy</span><span>${p.seeds} seeds</span><span>${p.wood} wood</span><span>${p.stone} stone</span><span>${p.crystals} crystals</span></div>`:''}<div class="dev-guide"><p><b>Move:</b> tap open ground. The wanderer follows a walkable route. Keyboard: WASD or arrow keys.</p><p><b>Gather:</b> harvest nearby trees, berries, stone, or grass. Food restores you; resources support your next intervention.</p><p><b>Tend:</b> spend seeds to nourish a patch. Discover three landmarks to plant three patches at once.</p><p><b>Build:</b> bridges connect water tiles, camps restore you, and sanctuaries nourish plants and repel wolves.</p><p><b>Explore:</b> discover eight seeded landmarks with lore and supplies. After six discoveries, hazards deal half damage.</p><p><b>Survive:</b> fire and nearby predators hurt. If you fall, you return to camp with discoveries intact and lose a quarter of your timber.</p></div>${p?.enabled?'<button id="build-camp" class="secondary dev-wide">Build camp here · 3 wood + 2 stone</button>':''}${check('follow','Follow the wanderer','The camera tracks you while walking.',eco.tweaks.follow)}${check('fogOfWar','Uncharted world','Hide land you have not yet explored.',eco.tweaks.fogOfWar)}${p?.enabled?'<button id="leave-world" class="secondary dev-wide">Return to observer mode</button>':''}<p class="dev-help">An experimental exploration loop, not a full RPG. There is no combat system or settlement AI yet.</p>`;
  if(active==='events')content=`<p class="dev-intro">Weather changes the rules. Disasters can destroy terrain and kill creatures. Every triggered event has an undo checkpoint.</p><label class="dev-field">Weather duration<select id="weather-duration"><option value="45">45 world seconds</option><option value="90">90 world seconds</option><option value="180">180 world seconds</option></select></label><div class="weather-grid">${Object.entries(WEATHERS).map(([id,name])=>`<button data-weather="${id}" class="weather-choice ${eco.currentWeather()===id?'active':''}" aria-pressed="${eco.currentWeather()===id}"><b>${name}</b><small>${({clear:'Restore ordinary weather.',rain:'Moisten soil and extinguish fires.',storm:'Heavy rain with occasional lightning.',fog:'Reduce creatures’ sight range.',snow:'Slow growth; replenish moisture.',drought:'Dry soil and deplete grass.',aurora:'Recharge crystals and light the sky.'})[id]}</small></button>`).join('')}</div><h3 class="dev-heading">Natural disasters</h3><div class="disaster-list">${[['fire','Wildfire','Ignite a dry patch. Water and rain limit the spread.'],['flood','Flood','Submerge riverbanks for 45 world seconds; fish find new routes.'],['meteor','Meteor strike','Leave fire, a crystal, and a new landmark to discover.'],['quake','Earthquake','Break vegetation and structures, exposing rock.'],['spores','Spore bloom','Grow a fungal patch and introduce fireflies and beetles.']].map(([id,title,desc])=>`<div class="disaster-entry"><div><b>${title}</b><p>${desc}</p></div><button data-disaster="${id}" class="secondary">Trigger</button></div>`).join('')}</div>${check('autoDisasters','Surprise events','Rare random disasters. Off by default.',eco.tweaks.autoDisasters)}`;
  if(active==='feel')content=`<p class="dev-intro">Change one variable and watch what happens. Changes apply to this world; Undo also restores tuning.</p><div class="dev-ranges">${[['growth','Plant growth',.25,3,.25,'×'],['hunger','Hunger rate',.25,3,.25,'×'],['birthRate','Reproduction',0,3,.25,'×'],['populationCap','Total creature ceiling',80,320,20,''],['shadow','Shadow strength',0,1,.1,''],['particles','Particles',0,2,1,'']].map(([id,label,min,max,step,unit])=>`<label class="dev-range"><span>${label}<output id="value-${id}">${eco.tweaks[id]}${unit}</output></span><input type="range" data-range="${id}" data-unit="${unit}" min="${min}" max="${max}" step="${step}" value="${eco.tweaks[id]}"></label>`).join('')}</div>${check('wildfires','Fire can spread','Drakes can ignite dry ground; water stops the spread.',eco.tweaks.wildfires)}${check('lore','Landmarks & lore','Show seeded ruins, springs, and forgotten places.',eco.tweaks.lore)}${check('shake','Impact motion','Small camera movement for meteor strikes and quakes.',eco.tweaks.shake)}${check('sound','Sound feedback','Soft, synthesised notes for actions and discoveries.',eco.tweaks.sound)}${check('haptics','Touch feedback','Short taps on devices that support vibration.',eco.tweaks.haptics)}<label class="dev-switch"><span><b>Gentle motion</b><small>Disable camera shake, hopping, flashes, and weather particles.</small></span><input id="dev-gentle" type="checkbox" ${reduced?'checked':''}></label><button id="reset-tuning" class="secondary dev-wide">Reset tuning to defaults</button>`;
  if(active==='journal'){const counts=eco.counts();content=`<div class="journal-summary"><span>${p?.discovered||0} / ${eco.landmarks.length} places</span><span>${eco.milestones.length} emergent outcomes</span><span>Day ${eco.day()}</span></div><details class="dev-details"><summary>Population census · ${eco.entities.length} creatures</summary><div class="census-grid">${Object.entries(SPECIES).map(([id,s])=>`<span>${spriteTag(id)}${s.plural}<b>${counts[id]||0}</b></span>`).join('')}</div></details><details class="dev-details"><summary>Experiments to chase</summary><p>Let deer carry berry seeds. Bring rain after a fire, then watch the ash bloom. Put wisps near crystals. Test whether a river can stop a wildfire.</p></details><div class="journal-entries">${eco.journal.length?eco.journal.map(e=>`<article><span>DAY ${e.day} · ${safe(e.kind).toUpperCase()}</span><h3>${safe(e.title)}</h3><p>${safe(e.text)}</p></article>`).join(''):'<p class="dev-empty">A story needs something to happen. Enter the world, run a scenario, or make a small intervention.</p>'}</div>`;}
  api.openDialog('dev','Dev tweaks',`<p class="dev-kicker">EXPERIMENTAL PLAYGROUND <span>Time pauses while this menu is open</span></p><nav class="dev-tabs" aria-label="Dev menu sections">${tabs.map(([id,title])=>`<button data-dev-tab="${id}" aria-current="${active===id?'page':'false'}" class="${active===id?'active':''}">${title}</button>`).join('')}</nav><div class="dev-content">${content}</div><div class="dev-feedback" id="dev-feedback" role="status">Changes are reversible. Close this menu to see the world respond.</div>`);
  $('#dialog').classList.add('dev-dialog');api.decorate($('#dialog'));bind();
 }
 function feedback(text){$('#dev-feedback').textContent=text;}
 function bind(){const{eco}=api.state();
  $$('[data-dev-tab]').forEach(b=>b.onclick=()=>open(b.dataset.devTab));
  $$('[data-place]').forEach(b=>b.onclick=()=>{api.closeDialog();api.selectTool(b.dataset.place);api.toast(`Tap the world to place ${b.dataset.place}.`);});
  $$('[data-add]').forEach(b=>b.onclick=()=>{let n=0;api.mutate(`adding ${b.dataset.add}`,()=>{n=eco.addSpecies(b.dataset.add,5);return n?{ok:true}:{ok:false,message:'No suitable habitat. Fish need water; land creatures need open ground.'};});feedback(n?`Added ${n} ${SPECIES[b.dataset.add].plural.toLowerCase()}. Close the menu to watch them.`:'No suitable habitat was found.');});
  $$('[data-option]').forEach(input=>input.onchange=()=>{api.mutate(`${input.dataset.option} setting`,()=>{eco.tweaks[input.dataset.option]=input.checked;return{ok:true};});if(input.dataset.option==='sound'&&input.checked)api.enableSound();feedback(`${input.closest('label').querySelector('b').textContent} ${input.checked?'enabled':'disabled'}.`);});
  $$('[data-range]').forEach(input=>{input.oninput=()=>{$(`#value-${input.dataset.range}`).textContent=input.value+input.dataset.unit;};input.onchange=()=>{api.mutate(`${input.dataset.range} setting`,()=>{eco.tweaks[input.dataset.range]=Number(input.value);return{ok:true};});feedback('Tuning updated. Close the menu to watch the effect.');};});
  $$('[data-weather]').forEach(b=>b.onclick=()=>{api.mutate('weather change',()=>eco.setWeather(b.dataset.weather,Number($('#weather-duration').value)));api.closeDialog();api.toast(`${WEATHERS[b.dataset.weather]} is set. Resume time if paused.`);});
  $$('[data-disaster]').forEach(b=>b.onclick=()=>{const result=api.mutate(b.dataset.disaster,()=>eco.disaster(b.dataset.disaster));if(result.ok){api.closeDialog();api.focusWorld(result.x,result.y);api.toast('Event triggered. Undo restores the world from before it.');}});
  $$('[data-scenario]').forEach(b=>b.onclick=()=>{api.mutate('scenario',()=>eco.scenario(b.dataset.scenario));api.closeDialog();api.afterWorld();if(eco.player?.enabled)api.enterPlayer(false);api.toast('Scenario running. Undo restores your previous world.');});
  if($('#apply-theme'))$('#apply-theme').onclick=()=>{api.mutate('theme',()=>{eco.theme=$('#dev-theme').value;eco.revision++;return{ok:true};});api.applyTheme();feedback('Theme applied. The terrain and creatures are preserved.');};
  if($('#generate-lab'))$('#generate-lab').onclick=()=>{const seed=$('#dev-seed').value.trim();if(!seed){$('#dev-seed').setAttribute('aria-invalid','true');feedback('Enter a seed to create a repeatable world.');return;}const env=$('#dev-environment').value,theme=$('#dev-theme').value;api.mutate('test world',()=>{eco.theme=theme;eco.tweaks.extraLife=true;eco.tweaks.lore=true;eco.reset(seed,env);return{ok:true};});api.closeDialog();api.afterWorld();api.toast('A new test world is alive. Undo restores the previous one.');};
  if($('#enter-world'))$('#enter-world').onclick=()=>{api.closeDialog();api.enterPlayer(true);};
  if($('#build-camp'))$('#build-camp').onclick=()=>{const result=api.mutate('building camp',()=>eco.playerAction('camp'));feedback(result.message);if(result.ok)open('player');};
  if($('#leave-world'))$('#leave-world').onclick=()=>{api.mutate('leaving the world',()=>{eco.player.enabled=false;return{ok:true};});api.closeDialog();api.leavePlayer();};
  if($('#dev-gentle'))$('#dev-gentle').onchange=e=>{api.setReduced(e.target.checked);feedback('Motion preference updated.');};
  if($('#reset-tuning'))$('#reset-tuning').onclick=()=>{api.mutate('tuning reset',()=>{Object.assign(eco.tweaks,{growth:1,hunger:1,birthRate:1,populationCap:220,shadow:.6,particles:1,shake:true,sound:false,haptics:false,autoDisasters:false,wildfires:true});return{ok:true};});open('feel');feedback('Tuning reset. Your world is preserved.');};
 }
 return{open};
}
